using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class UsersPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Users", "View"); return AdminDataService.GetList("Users"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Users", "View"); return AdminDataService.GetDefinitionMetadata("Users"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Users", "Delete"); return AdminDataService.Delete("Users", id); } } }
